const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.normalize('NFC').trim().toLocaleLowerCase('nn').replace(/\s+/g,' ');
let storageOK=true;function read(k,f){try{return JSON.parse(localStorage.getItem('nnlab-'+k))??f}catch{return f}}function save(k,v){try{localStorage.setItem('nnlab-'+k,JSON.stringify(v));return true}catch{storageOK=false;return false}}
let progress=read('progress',{answered:0,correct:0,sessions:0,topics:{},mistakes:[]}), draft=read('draft',''), verbs=[], quiz=null, direction='bm', lookupSerial=0;
progress.history??=Object.fromEntries((progress.mistakes||[]).map(id=>[id,{attempts:1,streak:0,wrong:true,lastSeen:0,dueAt:0}]));
const main=$('#main');
const attribution='<p class="attribution">Bokmålsordboka/Nynorskordboka, Universitetet i Bergen og Språkrådet, <a href="https://ordbokene.no" target="_blank" rel="noopener">ordbøkene.no</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC-BY 4.0</a>. Data er viste i eit forenkla oppsett. Øvingsverb er henta 20. oktober 2026.</p>';
const intro=(title,desc,tag='8.–10. TRINN')=>`<div class="eyebrow">${tag}</div><div class="intro"><div><h1>${title}</h1><p>${desc}</p></div></div>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
function go(p){location.hash=p}
const names={heim:'DIN NYNORSKKVARDAG',oving:'ØVINGSROMMET',ordbok:'ORDBOK & ORDHJELP',skriv:'SKRIVEVERKSTADEN',les:'LES & UTFORSK',reglar:'GRAMMATIKKGUIDEN',larar:'FOR LÆRAREN'};
function render(){const p=location.hash.slice(1)||'heim';lookupSerial++;if(p!=='oving'&&quiz?.checked){quiz.index++;quiz.checked=false}$('#breadcrumb').textContent=names[p]||names.heim;$$('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===p);if(a.dataset.page===p)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});({heim:home,oving:exercise,ordbok:dictionary,skriv:writing,les:reading,reglar:rules,larar:teacher}[p]||home)();window.scrollTo(0,0)}
function home(){main.innerHTML=`<div class="intro"><div><h1>Hei, språkutforskar.</h1><p>Små steg for å bli tryggare i nynorsk.</p></div><span class="pill">✧ &nbsp; Rom for å prøve</span></div><section class="hero"><div><div class="eyebrow">ORD FOR ORD. STEG FOR STEG.</div><h1>Gjer nynorsken<br>til din eigen.</h1><p>Finn orda, forstå mønstera og få fram det du meiner. Vi tek det ei øving om gongen.</p><div class="button-row"><button class="button" data-start="blanda">Start ei øvingsøkt <span>↗</span></button><a class="textlink" href="#ordbok">Slå opp eit ord →</a></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="wordcard"><small>INFINITIV</small><b>å skrive</b></div><div class="wordcard two"><small>PRETERITUM</small><b>skreiv</b></div><div class="wordcard three"><small>PRESENS</small><b>eg skriv.</b></div><span class="spark">✳</span><span class="art-dot"></span></div></section><div class="stats"><div class="stat"><span class="stat-icon">✓</span><div><strong>${progress.answered}</strong><small>oppgåver prøvde</small></div></div><div class="stat"><span class="stat-icon">✧</span><div><strong>${progress.sessions}</strong><small>økter fullførte</small></div></div><div class="stat"><span class="stat-icon">↗</span><div><strong>${progress.mistakes.length}</strong><small>oppgåver å øve meir på</small></div></div></div><div class="section-head"><h2>Kva vil du utforske?</h2><p>Vel det du treng akkurat no</p></div><div class="cards"><a class="card link" href="#oving"><div class="card-symbol">å</div><h3>Få tak på grammatikken</h3><p>Frå sterke verb til små komma. Øv, få ei forklaring og prøv igjen.</p><div class="card-bottom"><span>6 øvingstypar · ca. 5 min</span><b>↗</b></div></a><a class="card link" href="#ordbok"><div class="card-symbol orange">⇄</div><h3>Finn det rette ordet</h3><p>Slå opp bøying og tyding. Utforsk ord på nynorsk og bokmål.</p><div class="card-bottom"><span>Ordbok & tovegs ordhjelp</span><b>↗</b></div></a><a class="card link" href="#skriv"><div class="card-symbol purple">✎</div><h3>Gje teksten din liv</h3><p>Gjer språket tydelegare med konkrete råd og gode omskrivingar.</p><div class="card-bottom"><span>Skrivetips & tekstverkstad</span><b>↗</b></div></a></div><div class="lower-grid"><div class="daily"><div class="daily-mark">æ</div><div><div class="eyebrow" style="margin-bottom:6px">EIT ORD Å TA MED SEG</div><div class="daily-word">augneblink</div><p>Bokmål: øyeblikk. «Ein augneblink var alt stille.»</p></div></div><div class="note"><strong>Visste du dette?</strong><p>Du kan skrive både <b>å skrive</b> og <b>å skriva</b>. Nynorsk har rom for fleire godkjende former.</p><a class="textlink" href="#reglar">Bli kjend med valfridommen →</a></div></div>`;bindStarts()}
function bindStarts(){$$('[data-start]').forEach(b=>b.onclick=()=>startQuiz(b.dataset.start))}
function verbQuestions(){return verbs.flatMap(v=>[1,2,3].map(i=>({id:`v${v.id}-${i}`,topic:'verb',kind:'context',group:v.group,prompt:`${['','Bruk presens','Bruk preteritum','Bruk perfektum partisipp'][i]} av å ${v.word}: ${VERB_CONTEXTS[v.word]?.[i-1]||'Eg ___.'}`,drillPrompt:`Bøy å ${v.word} i ${['','presens','preteritum','perfektum partisipp (etter har)'][i]}.`,answers:v.forms[i],explain:verbExplanation(v),v,i}))) }
function pool(topic){const all=[...verbQuestions(),...QUIZZES];return topic==='blanda'?all:topic==='feil'?all.filter(q=>progress.mistakes.includes(q.id)):all.filter(q=>q.topic===topic)}
function shuffle(a){return Learning.shuffle(a)}
function practicePool(topic,mode=read('practice-mode','mixed')){const items=pool(topic);if(topic==='feil')return items;return items.filter(q=>mode==='mixed'||mode==='form'&&(q.topic==='verb'||q.kind==='form')||mode==='context'&&q.kind==='context'||mode==='explain'&&q.kind==='explain')}
function startQuiz(topic,group='alle'){const mode=$('#practice-mode')?.value||read('practice-mode','mixed');save('practice-mode',mode);let items=practicePool(topic,mode);if(group!=='alle')items=items.filter(x=>x.group===group||x.v?.word==='spele'&&group==='e-verb');if(!items.length){toast('Ingen oppgåver av denne typen i temaet. Vel «Alle oppgåvetypar».');return}let selected=topic==='feil'?shuffle(items).slice(0,10):Learning.select(items,progress.history||{},progress.answered);quiz={items:selected.map(q=>({...q,prompt:mode==='form'&&q.drillPrompt?q.drillPrompt:q.prompt})),index:0,correct:0,done:false,checked:false,wrong:[],topic,group,mode};if(location.hash!=='#oving'){location.hash='oving'}else showQuestion()}
function exercise(){if(quiz&&!quiz.done){showQuestion();return}main.innerHTML=intro('Eit lite steg. Litt tryggare.','Vel eit tema. Du får forklaringar undervegs og kan prøve på nytt.','ØVINGSROMMET')+`<section class="panel practice-options"><div><label for="practice-mode">Kva vil du øve på?</label><select id="practice-mode">${[['mixed','Alle oppgåvetypar'],['form','Finn forma · bøyingsdrill'],['context','Bruk forma · i setningar'],['explain','Forklar valet · vel ei grunngiving']].map(([v,t])=>`<option value="${v}" ${read('practice-mode','mixed')===v?'selected':''}>${t}</option>`).join('')}</select></div><p class="small">Nye oppgåver blir prioriterte, saman med nokre oppgåver du bør repetere. Repetisjon kjem etter fleire svar. Framgangen blir lagra på denne eininga.</p></section><div class="cards">${TOPICS.map((t,i)=>`<article class="card"><div class="card-symbol exercise-symbol ${i%3===1?'orange':i%3===2?'purple':''}">${t[3]}</div><h3>${t[1]}</h3><p>${t[2]}</p><div class="card-bottom"><span>${practicePool(t[0]).length} oppgåver · ${practicePool(t[0]).filter(q=>!progress.history?.[q.id]).length} uprøvde</span><button class="button secondary" data-start="${t[0]}" ${practicePool(t[0]).length?'':'disabled'}>Øv →</button></div></article>`).join('')}</div><div class="grid2" style="margin-top:25px"><div class="panel"><h2>Vel ei verbgruppe</h2><p class="small">Ei målretta økt med dei mønstera du vil bli trygg på.</p><div class="formrow"><div><label for="verbgroup">Verbgruppe</label><select id="verbgroup">${Object.keys(GROUPS).map(g=>`<option>${g}</option>`).join('')}</select></div><button class="button" id="verb-start" ${read('practice-mode','mixed')==='explain'?'disabled':''}>Start økt →</button></div></div><div class="panel"><h2>Prøv ein gong til</h2><p class="small">${progress.mistakes.length?`Du har ${progress.mistakes.length} oppgåver å øve meir på. Eit rett svar fjernar oppgåva frå denne lista.`:'Oppgåver du ikkje får til første gongen, blir samla her. Feil er ein del av læringa.'}</p><button class="button secondary" data-start="feil" ${progress.mistakes.length?'':'disabled'}>Øv på eigne feil ↗</button></div></div><p class="small muted">${verbs.length} verb · ${QUIZZES.length} andre grammatikkoppgåver. Økter er øving, ikkje karaktergrunnlag.</p>`;bindStarts();$('#practice-mode').onchange=()=>{save('practice-mode',$('#practice-mode').value);exercise();$('#practice-mode').focus()};$('#verb-start').onclick=()=>startQuiz('verb',$('#verbgroup').value)}
function showQuestion(){let q=quiz.items[quiz.index];if(!q){finishQuiz();return}main.innerHTML=intro('Prøv. Forstå. Bruk.','Les oppgåva, bruk eit hint om du treng det, og undersøk forklaringa etterpå.','ØVINGSROMMET')+`<div class="grid2"><section class="panel"><button class="back" id="quit">← Tilbake til temaa</button><div class="section-head"><span class="tag">${esc(q.v?.word==='spele'?'a-verb / e-verb':q.group||TOPICS.find(x=>x[0]===q.topic)?.[1])}</span><span class="small muted">Oppgåve ${quiz.index+1} av ${quiz.items.length}</span></div><div class="progress-track"><span style="width:${quiz.index/quiz.items.length*100}%"></span></div><h2 class="quiz-question">${esc(q.prompt)}</h2><form id="quiz-form" class="quiz-answer"><label for="answer">Svaret ditt</label>${q.choices?`<div class="choices explanation-choices">${shuffle(q.choices).map(c=>`<button class="choice" type="button" data-answer="${esc(c)}">${esc(c)}</button>`).join('')}</div>`:''}<input id="answer" autocomplete="off" spellcheck="false" placeholder="${q.answerMode==='sentence'?'Skriv heile setninga …':'Skriv svaret her …'}" ${q.choices?'hidden':'required'}><div class="button-row" style="margin-top:18px"><button class="button" type="submit">Sjekk svaret →</button><button class="plain" type="button" id="hint">Gje meg eit hint</button></div></form><div id="feedback" aria-live="polite"></div></section><aside><div class="panel"><div class="eyebrow">DET ER LOV Å UNDRE SEG</div><h2>Finn mønsteret.</h2><p>${esc((TOPIC_SUPPORT[q.topic]||TOPIC_SUPPORT.blanda).hint)}</p><div id="hintbox" class="tip" hidden>${esc(q.hint||(q.kind==='explain'?'Les alle alternativa. Kva forklaring kan du grunngi ut frå setninga?':q.explain))}</div><div class="mini-steps"><span>1. Prøv sjølv</span><span>2. Les forklaringa</span><span>3. Bruk i tekst</span></div></div><div class="note"><strong>Fleire former kan vere rette.</strong><p>Verbøvingane godtek alternativa i ordbokgrunnlaget. Store bokstavar og ekstra mellomrom påverkar ikkje svaret. I setningsoppgåver er sluttpunktum valfritt; komma og ordstilling må vere rette.</p></div></aside></div>`;$('#quit').onclick=()=>{quiz=null;exercise()};$('#hint').onclick=()=>{$('#hintbox').hidden=false};$('#quiz-form').onsubmit=e=>{e.preventDefault();checkAnswer()};$$('[data-answer]').forEach(b=>b.onclick=()=>{$('#answer').value=b.dataset.answer;$$('[data-answer]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});if(q.choices)$$('[data-answer]')[0]?.focus();else $('#answer').focus()}
function checkAnswer(){if(quiz.checked)return;const q=quiz.items[quiz.index],a=$('#answer').value;if(!norm(a)){toast(q.choices?'Vel ei forklaring først.':'Skriv eit svar først.');return}quiz.checked=true;const right=Learning.matches(q,a);progress.answered++;progress.correct+=+right;progress.history??={};progress.history[q.id]=Learning.record(progress.history[q.id],right,progress.answered);let p=progress.topics[q.topic]||{total:0,correct:0};p.total++;p.correct+=+right;progress.topics[q.topic]=p;if(right){quiz.correct++;progress.mistakes=progress.mistakes.filter(id=>id!==q.id)}else{quiz.wrong.push(q);if(!progress.mistakes.includes(q.id))progress.mistakes.push(q.id)}save('progress',progress);$('#answer').readOnly=true;$$('[data-answer]').forEach(b=>b.disabled=true);$('#quiz-form button[type=submit]').disabled=true;$('#feedback').innerHTML=`<div class="feedback ${right?'correct':''}"><strong>${right?'✓ Det stemmer!':'Nesten – sjå på mønsteret.'}</strong><p>Godkjent svar: <b>${q.answers.map(esc).join(' / ')}</b></p><p>${esc(q.explain)}</p>${q.v?`<div class="inflections">${q.v.forms.map((f,i)=>`<span>${i===0?'å ':i===3?'har ':''}${f.map(esc).join(' / ')}</span>`).join('')}</div>`:''}</div><button id="next" class="button" style="margin-top:20px">${quiz.index+1===quiz.items.length?'Sjå oppsummeringa':'Neste oppgåve'} →</button>`;$('#next').onclick=()=>{quiz.index++;quiz.checked=false;showQuestion()};$('#next').focus()}
function finishQuiz(){if(!quiz.done){progress.sessions++;save('progress',progress);quiz.done=true}main.innerHTML=intro('Godt jobba med økta.','Ta med deg eitt mønster vidare til din eigen tekst.','OPPSUMMERING')+`<div class="grid2"><div class="panel"><div class="result-number">${quiz.correct}<span class="muted" style="font-size:26px"> / ${quiz.items.length}</span></div><p>rette svar denne gongen</p><h2>${quiz.correct===quiz.items.length?'Mønstera sit!':'Du er i gang. Hald fram.'}</h2><p>${quiz.wrong.length?'Les formene under og prøv dei på nytt.':'Prøv ei blanda økt eller bruk tre av orda i eit eige avsnitt.'}</p>${quiz.wrong.map(q=>`<div class="progress-card"><strong>${esc(q.prompt)}</strong><small>${q.answers.map(esc).join(' / ')}</small></div>`).join('')}<div class="button-row"><button class="button" id="retry">${quiz.wrong.length?'Øv på desse igjen':'Ny økt'} →</button><button class="button secondary" id="topics">Vel eit anna tema</button></div></div><div class="panel"><span class="rule-icon">✎</span><h2>Frå øving til språk</h2><p>${esc((TOPIC_SUPPORT[quiz.topic]||TOPIC_SUPPORT.blanda).transfer)}</p><p class="small">Les teksten høgt. Forklar eitt språkval til ein medelev, og bruk ordboka når du er usikker.</p><a class="button secondary" href="#skriv">Opne skriveverkstaden ↗</a><p class="small" style="margin-top:20px">Resultatet viser denne økta. Det seier ikkje alt om skrivekompetansen din.</p></div></div>`;$('#retry').onclick=()=>{if(quiz.wrong.length){quiz={items:shuffle(quiz.wrong),index:0,correct:0,wrong:[],checked:false,done:false,topic:quiz.topic,group:quiz.group,mode:quiz.mode};showQuestion()}else startQuiz(quiz.topic,quiz.group||'alle')};$('#topics').onclick=()=>{quiz=null;exercise()}}
function dictionary(){main.innerHTML=intro('Finn orda du leitar etter.','Slå opp tyding og bøying, eller finn eit ord på den andre målforma.','ORDBOK & ORDHJELP')+`<div class="tabs"><button class="tab selected" id="official-tab">Ordbøkene · direkte oppslag</button><button class="tab" id="pairs-tab">Bokmål ⇄ nynorsk</button><button class="tab" id="saved-tab">Mine ord (${read('words',[]).length})</button></div><div id="dictionary-content"></div>`;$('#official-tab').onclick=()=>dictMode('official');$('#pairs-tab').onclick=()=>dictMode('pairs');$('#saved-tab').onclick=()=>dictMode('saved');dictMode('official')}
function dictMode(mode){lookupSerial++;pairViewId++;['official','pairs','saved'].forEach(x=>$('#'+x+'-tab').classList.toggle('selected',x===mode));const c=$('#dictionary-content');if(mode==='official'){c.innerHTML=`<div class="panel"><form id="lookup" class="searchform"><input id="word" aria-label="Ord å slå opp" placeholder="Søk etter eit ord, til dømes skrive …" required maxlength="100"><select id="dict" aria-label="Vel ordbok"><option value="nn">Nynorskordboka</option><option value="bm">Bokmålsordboka</option></select><button class="button">Slå opp ↗</button></form><p class="small muted" style="margin:12px 0 0">Søk i heile ordboka, også med bøygde former. Oppslaget krev nett.</p></div><div id="dict-results" aria-live="polite"><div class="panel"><h2>Ei ordbok er meir enn ei ordliste.</h2><p>Sjå kva ordet tyder, korleis det blir bøygd, og korleis det blir brukt. Prøv <button class="plain lookup-example" data-word="skrive">skrive</button>, <button class="plain lookup-example" data-word="kjensle">kjensle</button> eller <button class="plain lookup-example" data-word="bøker">bøker</button>.</p><div class="tip">Bokmålsordboka og Nynorskordboka er einspråklege ordbøker. Bruk fana «Bokmål ⇄ nynorsk» for appens utval av omsetjingsforslag.</div></div></div>${attribution}`;$('#lookup').onsubmit=e=>{e.preventDefault();lookup()};$$('.lookup-example').forEach(b=>b.onclick=()=>{$('#word').value=b.dataset.word;lookup()})}else if(mode==='pairs'){renderPairSearch(c)}else{const words=read('words',[]);c.innerHTML=`<div class="panel"><h2>Di eiga ordsamling</h2><p class="small">Orda blir lagra i denne nettlesaren. Bruk dei i ein ny tekst.</p>${words.length?words.map((w,i)=>`<div class="pair"><strong>${esc(w.word)}</strong><span class="tag">${w.dict==='nn'?'Nynorsk':'Bokmål'}</span><button class="plain saved-open" data-index="${i}">Slå opp ↗</button><button class="plain saved-remove" data-index="${i}" aria-label="Fjern ${esc(w.word)}">Fjern</button></div>`).join(''):'<div class="empty">Ingen ord lagra enno. Slå opp eit ord og vel «Lagre ord».</div>'}</div>`;$$('.saved-open').forEach(b=>b.onclick=()=>{const w=words[+b.dataset.index];dictMode('official');$('#word').value=w.word;$('#dict').value=w.dict;lookup()});$$('.saved-remove').forEach(b=>b.onclick=()=>{words.splice(+b.dataset.index,1);save('words',words);$('#saved-tab').textContent=`Mine ord (${words.length})`;dictMode('saved')})}}
async function api(url){const c=new AbortController(),t=setTimeout(()=>c.abort(),10000);try{const r=await fetch(url,{signal:c.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(t)}}
function contentText(o){if(!o)return '';let i=0;return String(o.content||o.text||'').replace(/\$/g,()=>{const it=(o.items||[])[i++];if(!it)return '';return it.text||(it.lemmas||[]).map(l=>l.lemma).join('/')||({e_l:'eller liknande',m_m:'med meir',o_l:'og liknande',t_d:'til dømes'}[it.id])||it.id||''})}
function definitions(a){let out=[];function walk(nodes){for(const n of nodes||[]){if(n.type_==='explanation'){let t=contentText(n);if(t)out.push(t)}if(n.elements)walk(n.elements)}}walk(a.body?.definitions);return [...new Set(out)].slice(0,7)}
async function lookup(){const w=$('#word').value.trim(),d=$('#dict').value;if(!w)return;const serial=++lookupSerial,box=$('#dict-results');box.innerHTML='<div class="panel loading">Leitar i ordboka …</div>';try{const result=await api(`https://ord.uib.no/api/articles?w=${encodeURIComponent(w)}&dict=${d}&scope=ei`);if(serial!==lookupSerial)return;const ids=result.articles?.[d]||[];if(!ids.length){const sug=await api(`https://ord.uib.no/api/suggest?q=${encodeURIComponent(w)}&dict=${d}&n=8&include=eis`);if(serial!==lookupSerial)return;let suggestions=[...new Set(Object.values(sug.a||{}).flat().map(x=>x[0]))].slice(0,8);box.innerHTML=`<div class="panel"><h2>Ingen direkte treff på «${esc(w)}»</h2><p>Prøv grunnforma eller sjekk den andre målforma.</p><div class="button-row">${suggestions.map(x=>`<button class="button secondary suggestion" data-word="${esc(x)}">${esc(x)}</button>`).join('')}</div><a class="textlink" href="https://ordbokene.no/${d==='nn'?'nno':'nob'}/search?q=${encodeURIComponent(w)}&dict=${d}" target="_blank" rel="noopener">Søk vidare i Ordbøkene ↗</a></div>`;$$('.suggestion').forEach(b=>b.onclick=()=>{$('#word').value=b.dataset.word;lookup()});return}const entries=await Promise.all(ids.slice(0,8).map(id=>api(`https://ord.uib.no/${d}/article/${id}.json`)));if(serial!==lookupSerial)return;box.innerHTML=entries.map(a=>{const ps=a.lemmas.flatMap(l=>l.paradigm_info||[]).filter(p=>!p.to);const inf=[...new Set(ps.flatMap(p=>p.inflection||[]).map(f=>f.word_form).filter(Boolean))];const name=a.lemmas.map(l=>l.lemma).join(' / ');return `<article class="panel dictionary-result"><div class="section-head"><span class="tag">${d==='nn'?'Nynorskordboka':'Bokmålsordboka'} · ${esc(a.lemmas[0]?.inflection_class||'ord')}</span><button class="plain save-word" data-word="${esc(a.lemmas[0]?.lemma||w)}" data-dict="${d}">＋ Lagre ord</button></div><h2>${esc(name)}</h2><ol class="dict-def">${definitions(a).map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="definition-label" style="margin-top:18px">Bøyingsformer · forenkla oversikt</div><div class="inflections">${inf.map(f=>`<span>${esc(f)}</span>`).join('')}</div><a class="textlink" href="https://ordbokene.no/${d==='nn'?'nno':'nob'}/${d}/${a.article_id}" target="_blank" rel="noopener">Full artikkel, døme og bøyingsmønster ↗</a></article>`}).join('')+(ids.length>8?`<p>Viser 8 av ${ids.length} artiklar. Avgrens søket eller sjå alle treff i <a href="https://ordbokene.no/search?q=${encodeURIComponent(w)}&dict=${d}" target="_blank" rel="noopener">Ordbøkene</a>.</p>`:'');$$('.save-word').forEach(b=>b.onclick=()=>{let words=read('words',[]);if(!words.some(x=>x.word===b.dataset.word&&x.dict===b.dataset.dict))words.push({word:b.dataset.word,dict:b.dataset.dict});save('words',words);$('#saved-tab').textContent=`Mine ord (${words.length})`;toast(storageOK?'Ordet er lagra i di ordsamling.':'Nettlesaren kunne ikkje lagre ordet.')})}catch{if(serial!==lookupSerial)return;box.innerHTML=`<div class="panel"><h2>Ordboka svarar ikkje akkurat no.</h2><p>Prøv på nytt, eller gå direkte til Ordbøkene. Appens skuleordliste fungerer framleis.</p><div class="button-row"><button class="button" id="retry-lookup">Prøv igjen</button><a class="button secondary" href="https://ordbokene.no/search?q=${encodeURIComponent(w)}&dict=${d}" target="_blank" rel="noopener">Opne Ordbøkene ↗</a></div></div>`;$('#retry-lookup').onclick=lookup}}
function writing(){renderWritingWorkshop()}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function rules(){main.innerHTML=intro('Mønstera bak orda.','Korte forklaringar. Konkrete døme. Eit oppslagsverk du kan ha ved sida av teksten.','GRAMMATIKKGUIDEN')+`<div class="grid2"><div>${RULES.map((r,i)=>`<details ${i===0?'open':''}><summary>${r[0]}</summary><div><p>${r[1]}</p><div class="tip">${r[2]}</div><p style="margin-top:14px">${r[3]}</p></div></details>`).join('')}</div><aside><div class="panel"><span class="rule-icon">å</span><h2>Slå opp eit øvingsverb</h2><label for="verb-select">Vel verb</label><select id="verb-select">${verbs.map((v,i)=>`<option value="${i}">å ${v.word}</option>`).join('')}</select><div id="verb-table"></div></div><div class="note"><strong>Rett form, rett samanheng.</strong><p>Oversiktene viser vanlege mønster. Nynorskordboka gir den fulle bøyinga og godkjende variantar.</p><a href="#ordbok" class="textlink">Til ordboka →</a></div>${attribution}</aside></div>`;const update=()=>{const v=verbs[+$('#verb-select').value];$('#verb-table').innerHTML=v?`<div class="table-scroll"><table><tbody>${['Infinitiv','Presens','Preteritum','Presens perfektum'].map((label,i)=>`<tr><th>${label}</th><td>${i===0?'å ':i===3?'har ':''}${v.forms[i].map(esc).join(' / ')}</td></tr>`).join('')}</tbody></table></div><p class="small" style="margin-top:16px">${verbExplanation(v)}</p>`:'<p>Verbgrunnlaget kunne ikkje lastast.</p>'};$('#verb-select').onchange=update;update()}
function reading(){main.innerHTML=intro('Les. Legg merke til. Prøv sjølv.','Korte tekstar som opnar for samtale, språkoppdaging og eiga skriving.','LES & UTFORSK')+`<div class="cards">${TEXTS.map((t,i)=>`<button class="card link" data-text="${i}" style="text-align:left"><div class="card-symbol ${i===1?'orange':i===2?'purple':''}">${['“','!','æ'][i]}</div><span class="eyebrow">${t.genre}</span><h3>${t.title}</h3><p>${t.questions[0]}</p><div class="card-bottom"><span>${t.time} · refleksjonsoppgåver</span><b>↗</b></div></button>`).join('')}</div><div class="note" style="margin-top:25px"><strong>Ein liten lesestrategi</strong><p>Før: Kva trur du teksten handlar om? Undervegs: Merk deg ord og stader du undrar deg over. Etter: Forklar kva du meiner, og vis til teksten.</p></div>`;$$('[data-text]').forEach(b=>b.onclick=()=>showText(+b.dataset.text))}
function showText(i){const t=TEXTS[i];main.innerHTML=`<button class="back" id="back-reading">← Alle tekstane</button><article class="panel"><div class="reading"><div class="eyebrow">${t.genre} · ${t.time}</div><h2>${t.title}</h2><small>Original øvingstekst for Nynorsklab</small>${t.text.map(p=>`<p style="margin-top:22px">${p}</p>`).join('')}</div></article><div class="grid2"><section class="panel"><h2>Tenk vidare</h2><ol>${t.questions.map(q=>`<li style="margin-bottom:14px">${q}</li>`).join('')}</ol><details><summary>Sjå rettleiing til samtalen</summary><div><p>${t.hint}</p></div></details></section><section class="panel"><label for="reading-notes">Dine tankar og språkfunn</label><textarea id="reading-notes" placeholder="Eg legg merke til …">${esc(read('reading-'+i,''))}</textarea><p class="small" id="reading-save">Notata blir lagra lokalt.</p><button class="button secondary" id="download-notes">Last ned notata ↓</button></section></div>`;$('#back-reading').onclick=reading;$('#reading-notes').oninput=()=>{$('#reading-save').textContent=save('reading-'+i,$('#reading-notes').value)?'Lagra på denne eininga.':'Kunne ikkje lagre. Last ned notata.'};$('#download-notes').onclick=()=>download('lesenotat.txt',t.title+'\n\n'+$('#reading-notes').value);window.scrollTo(0,0)}
function teacher(){main.innerHTML=intro('Eit verktøy for heile skriveprosessen.','Frå grammatisk mønster til ein tekst eleven kan stå inne for.','FOR LÆRAREN')+`<section class="hero" style="grid-template-columns:1fr;min-height:0"><div><div class="eyebrow">KLAR TIL VIKARTIMEN</div><h1 style="font-size:32px">Ei god økt på 45 minutt.</h1><p style="max-width:650px">Eit konkret opplegg med sjølvstendig arbeid, samtale og skriving. Kan brukast på storskjerm eller som individuelt arbeid når elevane har tilgang til sida.</p><div class="button-row"><button class="button" id="print-lesson">Skriv ut timeopplegget ↓</button><a class="textlink" href="#oving">Til øvingsrommet →</a></div></div></section><section class="panel lesson-block" id="lesson"><div class="section-head"><h2>Frå verb til forteljing</h2><span class="pill">45 min · 8.–10. trinn</span></div><p class="small">Læringsmål for økta: Eg kan bruke nokre verb i presens og preteritum, skrive eit samanhengande avsnitt og forklare ei språkleg endring.</p>${[['0–5 min','Aktiver språket','Skriv «I dag skriv eg» og «I går skreiv eg» på tavla. La elevane forklare kva som endrar seg. Kva liknar på dialekten deira?'],['5–15 min','Øv på eitt mønster','Elevane vel a-verb, e-verb eller sterke verb. Dei les tilbakemeldingane og noterer to verb dei vil ta med vidare.'],['15–22 min','Les saman','Les «Den tomme plassen». Finn verb i fortid og diskuter kva den siste setninga kan tyde.'],['22–37 min','Skriv og bearbeid','Skriv 80–150 ord om eit møte som endra noko. Bruk minst tre verb i fortid. Slå opp eitt ord, og gjer éi grunngitt omskriving.'],['37–42 min','Del eit språkval','I par: Les eit avsnitt og forklar ei endring. Bruk omgrep som preteritum, tekstbinding eller setningsstart.'],['42–45 min','Utgangslapp','Skriv: «Dette får eg betre til no …» og «Neste gong vil eg øve på …». Del med læraren på den måten klassen vanlegvis bruker.']].map(x=>`<div class="timeline-item"><span>${x[0]}</span><div><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}</section><div class="grid2"><section class="panel"><h2>Tilpass støtta</h2><p><strong>Meir støtte:</strong> Start med a-verb, ha grammatikkguiden open og skriv setningar i par. Bruk ordsamlinga som støtte.</p><p><strong>Meir utfordring:</strong> Bland verbgrupper, samanlikn alternative formuleringar og forklar kva språkvala gjer med teksten.</p><p class="small">Dette er forslag til differensiering, ikkje ei fast fordeling av kompetansemål mellom 8., 9. og 10. trinn.</p></section><section class="panel"><h2>Kva er nyttig å sjå etter?</h2><div class="checklist">${['Bruker eleven det øvde mønsteret i eigen tekst?','Kan eleven forklare og grunngi eit språkval?','Blir teksten tydelegare etter bearbeiding?','Bruker eleven ordboka med forståing for tyding og samanheng?'].map(t=>`<label><input type="checkbox">${t}</label>`).join('')}</div><p class="small">Appen gir ikkje karakterar. Øvingsresultat er smal informasjon og må sjåast saman med elevtekstar og samtalar.</p></section></div><section class="panel"><div class="eyebrow">FAGLEG GRUNNLAG · KONTROLLERT 20.10.2026</div><h2>Læreplanen → konkrete læringshandlingar</h2><p>NOR01-08 gjeld frå august 2026. Mi didaktiske tolking er at grammatikktrening gir størst verdi når eleven bruker kunnskapen i lesing, skriving og samtale.</p><div class="table-scroll"><table><thead><tr><th>Prioritering i planen, parafrasert</th><th>Slik støttar appen arbeidet</th></tr></thead><tbody><tr><td>Rettskriving, bøying og tekstbinding på begge målformer</td><td>Øvingar med forklaring, ordbokoppslag og bruk i eigen tekst.</td></tr><tr><td>Grammatisk fagspråk og bearbeiding</td><td>Forklare eit mønster og grunngi ei omskriving.</td></tr><tr><td>Lesing og refleksjon over innhald og språk</td><td>Korte modelltekstar med opne spørsmål og språkoppdrag.</td></tr><tr><td>Formål, mottakar og sjanger</td><td>Skriveoppdrag og råd som må vurderast i samanheng.</td></tr><tr><td>Språkhistorie, variasjon og haldningar</td><td>Samanlikning av dialekt, nynorsk og bokmål; refleksjonsspørsmål.</td></tr></tbody></table></div><p class="small" style="margin-top:18px">Nynorsk kan vere hovudmål eller sidemål. Appen støttar delar av norskfaget; lengre lesing, litteraturarbeid, munnleg samhandling og lærarrettleiing må òg få plass. Planen legg vekt på variert kompetanse og vidare læring. Ved vurdering av sidemål skal kortare formell opplæringstid takast med i vurderinga.</p><a class="textlink" href="https://www.udir.no/lk20/nor01-08/kompetansemaal-og-vurdering/kv1110" target="_blank" rel="noopener">Les kompetansemåla og vurderingsteksten hos Udir ↗</a></section><section class="panel"><h2>Ordbok, omsetjing og fagleg presisjon</h2><p>Den direkte ordbokfunksjonen søkjer i heile Nynorskordboka eller Bokmålsordboka. Dette er to einspråklege ordbøker, ikkje ei komplett tospråkleg omsetjingsordbok.</p><p>Ordparlista er utvida med ${LEX_META.words.toLocaleString('nb')} oppføringar for ord og uttrykk og ${LEX_META.names.toLocaleString('nb')} namneoppføringar frå Apertium. Ho har òg ${PAIRS.length} skuleordpar med korte forklaringar. Ordklasse og omsetjingsretning er bevarte. Lista er omfattande, men ikkje ei garanti for alle ord, bøyingar eller tydingar. Kontroller gjeldande skrivemåte og kontekst i Ordbøkene. Kjelder, lisens og nedlastbare kjeldedata ligg i ordparfana.</p><p>Verbgrunnlaget omfattar ${verbs.length} verb med alternative former frå UiB/Språkrådet. Andre øvingar og modelltekstar er laga for appen. Skriveguiden skil mellom skrivemåte, grammatikk og stil, markerer tekststader og lèt eleven bruke eller avvise forslag. Sitat blir hoppa over som standard, og endringar kan angrast. Guiden er regelbasert og erstattar ikkje full språkvask.</p>${attribution}</section><section class="panel"><h2>Lagring og tilgang</h2><p>Framgang, utkast, lesenotat og lagra ord blir lagra i nettlesaren på denne eininga. Ingen elevkonto eller læraroversikt er bygd inn. På ein delt maskin bør eleven laste ned arbeidet og nullstille etter seg. Når du nullstiller, blir utkast og notat òg sletta.</p><p>Ordboksøk blir sende til UiB. Skrivefeltet blir handsama lokalt og blir ikkje sendt til ei KI-teneste. Sida hentar skrifttypar frå Google Fonts. Denne utgåva er offentleg tilgjengeleg på GitHub Pages. Elevane treng ikkje konto. Lokal lagring følgjer nettlesaren og nettadressa; arbeid frå Sites-utgåva blir ikkje automatisk flytta hit.</p><button class="button secondary" id="reset-teacher">Nullstill lokale data</button></section><section class="panel sources"><h2>Kjelder og vidare arbeid</h2><a href="https://www.udir.no/lk20/nor01-08/kompetansemaal-og-vurdering/kv1110" target="_blank" rel="noopener">Udir: mål etter 10. trinn ↗</a><a href="https://www.udir.no/lk20/nor01-08/gyldighet-og-innfoering?lang=nno" target="_blank" rel="noopener">Udir: gyldig læreplan ↗</a><a href="https://ordbokene.no" target="_blank" rel="noopener">Bokmålsordboka og Nynorskordboka ↗</a><a href="https://ordbokene.no/nno/about/open-data" target="_blank" rel="noopener">Ordbokdata og lisens ↗</a><a href="https://sprakradet.no/" target="_blank" rel="noopener">Språkrådet ↗</a><a href="https://nynorsksenteret.no/ungdomsskule" target="_blank" rel="noopener">Nynorsksenteret: ungdomsskule ↗</a></section>`;$('#print-lesson').onclick=()=>{document.body.classList.add('print-lesson');window.print();document.body.classList.remove('print-lesson')};$('#reset-teacher').onclick=resetData}
function resetData(){if(!confirm('Vil du slette lokal framgang, lagra ord, utkast og lesenotat? Last ned tekst du vil ta vare på først.'))return;try{Object.keys(localStorage).filter(k=>k.startsWith('nnlab-')).forEach(k=>localStorage.removeItem(k))}catch{}progress={answered:0,correct:0,sessions:0,topics:{},mistakes:[]};draft='';quiz=null;render();toast('Lokale data er nullstilte.')}
$('.skip').onclick=e=>{e.preventDefault();main.focus()};
$('#reset').onclick=resetData;
window.addEventListener('hashchange',render);
(async()=>{try{const r=await fetch('verbs.json');if(!r.ok)throw Error();verbs=await r.json()}catch{toast('Verbgrunnlaget kunne ikkje lastast. Prøv å laste sida på nytt.')}render()})();
